type Asset = { symbol: string; name?: string; price: number; change: number; change1h?: number; change7d?: number; volume: number; marketCap?: number; rank?: number; circulatingSupply?: number; listedAt?: number; source?: string };
type Pulse = { symbol: string; price: number; change: number; volume: number };
type MarketResponse = { online: boolean; source: string; updatedAt: string; assets: Asset[] };
type Route = 'home' | 'markets' | 'charts' | 'scanner' | 'agent' | 'qa' | 'vision' | 'premium' | 'portfolio' | 'alerts';
const fallback: Asset[] = [
  { symbol: 'BTC', name: 'Bitcoin', price: 67842, change: 2.41, volume: 0 },
  { symbol: 'ETH', name: 'Ethereum', price: 3421, change: 1.86, volume: 0 },
  { symbol: 'SOL', name: 'Solana', price: 188.4, change: 4.12, volume: 0 },
  { symbol: 'BNB', name: 'BNB', price: 612.18, change: -0.73, volume: 0 },
];
const root = document.getElementById('app');
if (!root) throw new Error('App root missing');
let assets = fallback;
let pulse: { gainers: Pulse[]; losers: Pulse[] } = { gainers: [], losers: [] };
let discovery: { totalMarkets: number; newlyListed: Asset[]; trending: Array<{ symbol: string; name: string }>; pumpers: Asset[] } = { totalMarkets: 0, newlyListed: [], trending: [], pumpers: [] };
let route: Route = getRoute();
let marketInitialized = false;
let marketPage = 1;
let homeMarketPage = 1;
function getRoute(): Route { const key = location.hash.replace('#/', '').split('?')[0]; return ['home','markets','charts','scanner','agent','qa','vision','premium','portfolio','alerts'].includes(key) ? key as Route : 'home'; }
function money(v: number): string { return v >= 1000 ? `${v.toLocaleString(undefined, { maximumFractionDigits: 0 })}` : `${v.toLocaleString(undefined, { maximumFractionDigits: 2 })}`; }
function esc(value: unknown): string { return String(value ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function nav(label: string, target: Route): string { return `<a class="${route === target ? 'active' : ''}" href="#/${target}">${label}</a>`; }
function helpButton(topic: string): string { return `<button class="help-btn" data-help="${esc(topic)}" aria-label="How this works">?</button>`; }
function marketSnapshot(): string {
  const valid = assets.filter(a => Number.isFinite(a.price) && a.price > 0);
  const btc = valid.find(a => a.symbol === 'BTC');
  const eth = valid.find(a => a.symbol === 'ETH');
  const sol = valid.find(a => a.symbol === 'SOL');
  const positive = valid.filter(a => a.change > 0).length;
  const negative = valid.filter(a => a.change < 0).length;
  const totalCap = valid.reduce((sum, a) => sum + (a.marketCap || 0), 0);
  const btcDom = totalCap > 0 && btc?.marketCap ? (btc.marketCap / totalCap) * 100 : 0;
  const gainers = [...valid].filter(a => a.change > 0).sort((a, b) => b.change - a.change).slice(0, 10);
  const tickerItems = gainers.length ? gainers.map((a, i) => `<a class="snapshot-gainer" href="#/markets" data-asset="${esc(a.symbol)}"><span class="gainer-rank">${i + 1}</span><b>${esc(a.symbol)}</b><span class="gainer-price">${money(a.price)}</span><strong>+${a.change.toFixed(2)}%</strong></a>`).join('') : '<span class="snapshot-empty">Waiting for live gainers…</span>';
  return `<section class="market-snapshot" aria-label="Live top 10 daily gainers"><div class="snapshot-inner"><span class="snapshot-label"><span class="pulse"></span>MARKET SNAPSHOT <em>TOP 10 GAINERS</em></span><div class="snapshot-ticker"><div class="snapshot-track">${tickerItems}${tickerItems}</div></div><span class="snapshot-live">LIVE · 15s</span></div></section>`;
}

function shell(content: string): void {
  root!.innerHTML = `<div class="app-shell"><header class="topbar"><a class="brand" href="#/home"><span class="brand-mark">CP</span><span>CryptoPilot <b>AI</b></span></a><nav>${nav('Overview','home')}${nav('Markets','markets')}${nav('Charts','charts')}${nav('AI Scanner','scanner')}${nav('AI Agent','agent')}${nav('QA Agent','qa')}${nav('Trade Vision','vision')}${nav('Portfolio','portfolio')}${nav('Alerts','alerts')}${nav('Premium','premium')}</nav><button class="mobile-menu" id="mobileMenu" aria-label="Open menu">☰</button><button class="ghost" id="signin">Sign in / Register</button></header><div class="live-strip"><span class="pulse"></span><span id="liveLabel">MARKET ENGINE CONNECTING</span><span>•</span><span>15s live refresh</span><span>•</span><span>Non-custodial</span><span>•</span><span>Research only</span></div>${marketSnapshot()}<main>${content}</main><footer><span>© 2026 CryptoPilot AI</span><span>Market intelligence · AI research · Risk tools</span></footer></div>`;
  document.getElementById('signin')?.addEventListener('click', openSignin);
  document.getElementById('mobileMenu')?.addEventListener('click', openMobileMenu);
  bindHelp();
  void refreshMarketStatus();
  void syncAuthButton();
}
function assetCard(a: Asset): string { return `<div class="market-card" data-asset="${esc(a.symbol)}" role="button" tabindex="0"><span class="card-help">${helpButton(`asset:${a.symbol}`)}</span><div class="asset"><span class="coin-icon asset-symbol" style="--coin-color:${coinColor(a.symbol)}">${esc(a.symbol.slice(0, 5))}</span><div><b class="asset-symbol-label">${esc(a.symbol)} <em>/USDT</em></b><small>${esc(a.name || a.symbol)}</small></div></div><div class="asset-price-line"><strong>${money(a.price)}</strong><span class="${a.change >= 0 ? 'green' : 'red'}">${a.change >= 0 ? '+' : ''}${a.change.toFixed(2)}%</span></div><div class="spark live"><i></i><i></i><i></i><i></i><i></i></div></div>`; }
function coinColor(symbol: string): string { const colors: Record<string, string> = { BTC: '#f7931a', ETH: '#8b9cff', SOL: '#66f5c4', BNB: '#f3ba2f', XRP: '#b8c5d6', ADA: '#5b8cff', DOGE: '#c9a64b', TRX: '#ef3340', TON: '#5a9cff', AVAX: '#e84142', LINK: '#2a5ada', DOT: '#e6007a', SUI: '#6fbcff', PEPE: '#6cc84a', SHIB: '#f3a34b' }; return colors[symbol] || '#7fdfff'; }
function coinIcon(symbol: string): string { const s = symbol.toLowerCase(); return `<span class="coin-icon" style="--coin-color:${coinColor(symbol)}"><img src="https://assets.coincap.io/assets/icons/${encodeURIComponent(s)}@2x.png" alt="${esc(symbol)} logo" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none';this.nextElementSibling?.classList.remove('hidden')"><span class="coin-fallback hidden">${esc(symbol.slice(0,5))}</span></span>`; }
function pulseTicker(rows: Pulse[], positive: boolean): string { return rows.slice(0,15).map((a,i)=>`<button class="pulse-row" data-asset="${esc(a.symbol)}"><span class="row-rank">${i+1}</span>${coinIcon(a.symbol)}<span class="row-name"><b>${esc(a.symbol)} <em>/USDT</em></b><small>${esc(a.symbol)}</small></span><span class="row-price">${money(a.price)}</span><strong class="${positive?'green':'red'}">${a.change>=0?'+':''}${a.change.toFixed(2)}%</strong></button>`).join(''); }
function riskWidget(): string {
  const valid = assets.filter(a => Number.isFinite(a.change) && Number.isFinite(a.price) && a.price > 0);
  const positive = valid.filter(a => a.change > 0).length;
  const negative = valid.filter(a => a.change < 0).length;
  const flat = Math.max(0, valid.length - positive - negative);
  const downsideShare = valid.length ? negative / valid.length : 0.5;
  const averageMove = valid.length ? valid.reduce((sum, a) => sum + Math.abs(a.change), 0) / valid.length : 0;
  const score = Math.min(100, Math.max(5, Math.round(downsideShare * 65 + Math.min(25, averageMove * 5) + (positive === 0 && negative > 0 ? 10 : 0))));
  const riskLevel = score < 40 ? 'LOW RISK' : score < 65 ? 'MODERATE RISK' : 'HIGH RISK';
  const riskClass = score < 40 ? 'risk-low' : score < 65 ? 'risk-mid' : 'risk-high';
  const riskColor = score < 40 ? '#43d6a2' : score < 65 ? '#f3c969' : '#ff6b7a';
  const avgVol = valid.length ? valid.reduce((s,a)=>s+(a.volume||0),0)/valid.length : 0; const breadthPressure = valid.length ? Math.abs(positive-negative)/valid.length : 0; const score2 = Math.min(100, Math.max(5, Math.round(downsideShare*58 + Math.min(28,averageMove*5.5) + (breadthPressure<.08?10:0)))); const level = score2<35?'LOW RISK':score2<65?'MODERATE RISK':'HIGH RISK'; const cls = score2<35?'risk-low':score2<65?'risk-mid':'risk-high'; const color = score2<35?'#43d6a2':score2<65?'#f3c969':'#ff6b7a'; return `<div class="hero-card risk-widget ${cls}"><div class="card-head"><div><span>Market Risk Score</span><small class="risk-subtitle">Live breadth · volatility · downside pressure</small></div><span class="status">LIVE</span>${helpButton('risk')}</div><div class="risk-visual"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="risk-ring" style="--risk-score:${score2}%;--risk-color:${color}"><div><strong>${score2}</strong><small>/100</small></div></div></div><div class="risk-scale"><span>LOW</span><span>MODERATE</span><span>HIGH</span></div><div class="risk-caption"><b>${level}</b><span>${positive.toLocaleString()} positive · ${negative.toLocaleString()} negative</span></div><div class="risk-bar"><i style="width:${score2}%;background:${color}"></i></div><div class="risk-feed"><span>Market breadth <b>${valid.length.toLocaleString()} assets · ${flat.toLocaleString()} flat</b></span><span>Average move <b>${averageMove.toFixed(2)}% · Avg volume ${money(avgVol)}</b></span></div><div class="risk-mini-grid"><span><i class="dot green-dot"></i>Positive <b>${positive.toLocaleString()}</b></span><span><i class="dot yellow-dot"></i>Flat <b>${flat.toLocaleString()}</b></span><span><i class="dot red-dot"></i>Negative <b>${negative.toLocaleString()}</b></span></div></div>`; }
const moverSparkCache = new Map<string, { points: number[]; at: number }>(); function moverSparkline(symbol: string): string { return `<span class="mover-sparkline" data-spark-symbol="${esc(symbol)}"><span class="spark-loading">· · ·</span></span>`; } async function hydrateMoverSparklines(): Promise<void> { if (route !== 'home' && route !== 'markets') return; const nodes = Array.from(document.querySelectorAll<HTMLElement>('[data-spark-symbol]')); for (let i = 0; i < nodes.length; i += 8) { const batch = nodes.slice(i, i + 8); await Promise.all(batch.map(async node => { const symbol = node.dataset.sparkSymbol || ''; if (!symbol) return; try { const cached = moverSparkCache.get(symbol); const candles = cached && Date.now() - cached.at < 60000 ? cached.points : (await fetchClientCandles(symbol, '1h', 24)).map(c => c.close); if (!candles.length) throw new Error('No sparkline data'); moverSparkCache.set(symbol, { points: candles, at: Date.now() }); const min = Math.min(...candles), max = Math.max(...candles), range = max - min || Math.max(1, max * 0.001); const points = candles.map((value, index) => `${(index / Math.max(1, candles.length - 1)) * 100},${34 - ((value - min) / range) * 28}`).join(' '); const last = candles[candles.length - 1], first = candles[0]; node.innerHTML = `<svg viewBox="0 0 100 36" preserveAspectRatio="none" aria-label="${esc(symbol)} 24 hour trend"><polyline points="${points}" fill="none" stroke="${last >= first ? '#43d6a2' : '#ff6b7a'}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`; } catch { node.innerHTML = '<span class="spark-fallback">—</span>'; } })); } } function moversBoard(): string { const ranked = [...assets].filter(a => Number.isFinite(a.price) && a.price > 0).sort((a,b)=>(b.marketCap||0)-(a.marketCap||0)||(b.volume||0)-(a.volume||0)).slice(0,500); const totalPages = Math.max(1, Math.ceil(ranked.length / 50)); if(homeMarketPage > totalPages) homeMarketPage = totalPages; const start = (homeMarketPage - 1) * 50; const pageRows = ranked.slice(start, start + 50); return `<section class="section"><div class="section-title"><div><span class="kicker">MARKET MOVERS</span><h2>What’s moving now ${helpButton('movers')}</h2><p class="movers-subtitle">Top 500 by live market value · updated automatically · click any coin for trader intelligence</p></div><span class="status">LIVE · TOP 500</span></div><div class="movers-board panel"><div class="movers-board-head"><span>#</span><span>Coin</span><span>Price</span><span>24h Movement</span><span>24h Volume</span><span>Market Cap</span></div><div class="movers-board-scroll">${pageRows.map((a,i)=>{const positive=a.change>=0;return `<button class="mover-table-row" data-asset="${esc(a.symbol)}"><span class="rank">${start+i+1}</span><span class="mover-coin">${coinIcon(a.symbol)}<span><b>${esc(a.name||a.symbol)}</b><small>${esc(a.symbol)}</small></span></span><span class="mover-price">${money(a.price)}</span><strong class="${positive?'green':'red'}">${positive?'+':''}${a.change.toFixed(2)}%</strong><span class="mover-stat"><b>${money(a.volume)}</b></span><span class="mover-stat"><b>${a.marketCap?money(a.marketCap):'—'}</b></span></button>`;}).join('')||'<p class="muted">Loading the live top-500 market…</p>'}</div><div class="market-pagination home-market-pagination"><button class="secondary" data-home-market-page="prev" ${homeMarketPage<=1?'disabled':''}>← Previous</button><span>Page <b>${homeMarketPage}</b> of <b>${totalPages}</b> · Showing ${pageRows.length?start+1:0}-${Math.min(start+50,ranked.length)} of ${ranked.length}</span><button class="secondary" data-home-market-page="next" ${homeMarketPage>=totalPages?'disabled':''}>Next →</button></div></div></section>`; }
function discoveryPanel(): string { return `<section class="section"><div class="section-title"><div><span class="kicker">MARKET MOVERS</span><h2>Live movement board ${helpButton('movers')}</h2></div><span class="status">LIVE</span></div><div class="movers-grid"><div class="panel mover-panel"><div class="panel-title"><div><span class="kicker">PUMP WATCH</span><h3>Rapid movers</h3></div><span class="status">LIVE</span></div><div class="mover-scroll">${discovery.pumpers.slice(0,15).map((a,i)=>`<button class="list-row" data-asset="${esc(a.symbol)}"><span class="rank">${i+1}</span>${coinIcon(a.symbol)}<span class="mover-symbol"><b>${esc(a.symbol)}</b><small>/USDT</small></span><span class="green">+${a.change.toFixed(2)}%</span><span>${money(a.price)}</span></button>`).join('')||'<p class="muted">Scanning momentum…</p>'}</div></div><div class="panel mover-panel"><div class="panel-title"><div><span class="kicker">TOP GAINERS</span><h3>Strongest movers</h3></div><span class="status">LIVE</span></div><div class="mover-scroll">${pulse.gainers.slice(0,15).map((a,i)=>`<button class="list-row" data-asset="${esc(a.symbol)}"><span class="rank">${i+1}</span>${coinIcon(a.symbol)}<span class="mover-symbol"><b>${esc(a.symbol)}</b><small>/USDT</small></span><span class="green">+${a.change.toFixed(2)}%</span><span>${money(a.price)}</span></button>`).join('')||'<p class="muted">Scanning gainers…</p>'}</div></div><div class="panel mover-panel"><div class="panel-title"><div><span class="kicker">TOP LOSERS</span><h3>Biggest drops</h3></div><span class="status">LIVE</span></div><div class="mover-scroll">${pulse.losers.slice(0,15).map((a,i)=>`<button class="list-row" data-asset="${esc(a.symbol)}"><span class="rank">${i+1}</span>${coinIcon(a.symbol)}<span class="mover-symbol"><b>${esc(a.symbol)}</b><small>/USDT</small></span><span class="red">${a.change.toFixed(2)}%</span><span>${money(a.price)}</span></button>`).join('')||'<p class="muted">Scanning losers…</p>'}</div></div></div></section>`; }
function homeView(): string { return `<section class="hero"><div><span class="eyebrow"><span class="pulse"></span>AI-POWERED CRYPTO INTELLIGENCE</span><h1>Know what the market is doing <span>before you act.</span></h1><p>CryptoPilot turns live market data into understandable signals, risk context and research missions — without pretending to predict the future.</p><div class="hero-actions"><a class="primary" href="#/markets">Open Market Terminal</a><a class="secondary" href="#/agent">Run AI Agent</a></div><div class="trust-row"><span>✓ Live market data</span><span>✓ AI reasoning</span><span>✓ No trade execution</span></div></div>${riskWidget()}</section>${moversBoard()}<section class="section three"><div class="feature panel"><span class="feature-icon">◈</span>${helpButton('scanner')}<h3>AI Scanner</h3><p>Rank market attention by momentum, direction and risk.</p><a href="#/scanner">Open scanner →</a></div><div class="feature panel"><span class="feature-icon">✦</span>${helpButton('agent')}<h3>AI Agent</h3><p>Ask a research question. The agent fetches fresh context and builds a brief.</p><a href="#/agent">Run agent →</a></div><div class="feature panel"><span class="feature-icon">▣</span>${helpButton('screenshot')}<h3>Screenshot AI</h3><p>Upload a trading-screen screenshot and let AI read the setup, risk and what you could improve.</p><a href="#/vision">Analyze a screenshot →</a></div></section><section class="section cta premium-cta"><div><span class="kicker">PREMIUM ACCESS</span><h2>Unlock the full CryptoPilot intelligence workspace.</h2><p>Advanced scanner, AI missions, alerts, chart intelligence and Trade Vision — all for <b>3 USDT / 30 days</b>.</p></div><a class="primary premium-cta-button" href="#/premium"><span>UNLOCK PREMIUM</span><strong>3 USDT · 30 DAYS →</strong></a></section>`; }
function marketsView(): string { return `<section class="page-head"><div><span class="kicker">MARKET TERMINAL</span><h1>Top 500 crypto markets by market value.</h1><p>${discovery.totalMarkets.toLocaleString()} live markets are available. CryptoPilot presents the core market fields traders expect — price, 24h movement, 24h volume and market cap — with live data and one-click coin research.</p></div><button class="secondary" id="refreshMarkets">↻ Refresh data</button></section><section class="section"><div class="market-tools"><input id="marketSearch" class="form-input" placeholder="Search any coin, token or symbol…" aria-label="Search all markets" /><select id="marketSort" class="form-input"><option value="marketCap">Market cap rank</option><option value="volume">24h volume</option><option value="change">24h performance</option><option value="change1h">1h performance</option><option value="change7d">7d performance</option><option value="price">Price</option><option value="name">Name</option></select></div><div class="market-filter-row"><button class="chip active" data-market-filter="all">All markets</button><button class="chip" data-market-filter="gainers">Gainers</button><button class="chip" data-market-filter="losers">Losers</button><button class="chip" data-market-filter="volume">High volume</button><span class="market-filter-note">Live universe · click a row for the specialist terminal</span></div><div class="market-universe-note"><b>Trader market board:</b> live market-cap ranking with <b>Price</b>, <b>24h Movement</b>, <b>24h Volume</b> and <b>Market Cap</b>. Clean core fields, live data, and one-click coin research.</div><div id="marketResults" class="market-table-wrap"></div></section>`; }
function marketPulse(a: Asset): { label: string; className: string } { const move = Math.abs(a.change || 0); if (move >= 7) return { label: 'HOT MOVE', className: 'pulse-hot' }; if (move >= 3) return { label: a.change >= 0 ? 'MOMENTUM' : 'CAUTION', className: a.change >= 0 ? 'pulse-up' : 'pulse-down' }; if (move < 0.5) return { label: 'STABLE', className: 'pulse-stable' }; return { label: a.change >= 0 ? 'POSITIVE' : 'SOFT', className: a.change >= 0 ? 'pulse-up' : 'pulse-down' }; }
function marketPct(value: number | undefined): string { return Number.isFinite(value) ? `${(value as number) >= 0 ? '+' : ''}${(value as number).toFixed(2)}%` : '—'; }
function marketTableRows(rows: Asset[], offset = 0): string { return rows.map((a, i) => { const pulse = marketPulse(a); return `<button class="market-table-row" data-asset="${esc(a.symbol)}"><span class="market-rank">${a.rank || offset + i + 1}</span><span class="market-coin">${coinIcon(a.symbol)}<span><b>${esc(a.name || a.symbol)}</b><small>${esc(a.symbol)} /USDT</small></span></span><strong class="market-price">${money(a.price)}</strong><span class="${a.change >= 0 ? 'green' : 'red'} market-movement">${marketPct(a.change)}</span><span class="market-stat-main">${money(a.volume)}</span><span class="market-stat-main">${a.marketCap ? money(a.marketCap) : '—'}</span></button>`; }).join(''); }
function chartsView(): string { const primary = assets.find(a => a.symbol === 'BTC') || assets[0] || fallback[0]; return `<section class="page-head"><div><span class="kicker">LIVE CHART TERMINAL</span><h1>Read price action clearly.</h1><p>Choose any loaded market, switch timeframe and follow fresh candles. The terminal keeps the latest REST history on screen and upgrades to a live Binance WebSocket stream when available.</p></div><span class="agent-badge">LIVE · BINANCE</span></section><section class="section"><div class="panel chart-panel"><div class="chart-head"><div><span class="kicker">PRICE ACTION · USDT</span><h2><span id="chartsSymbol">${esc(primary.symbol)}</span>/USDT <span id="chartsPrice" class="muted">${money(primary.price)}</span></h2><span class="muted chart-context">Interactive history · drag / wheel zoom · live updating · research only</span></div><div class="chart-toolbar"><select id="chartsAsset" class="form-input">${assets.slice(0,300).map(a=>`<option value="${esc(a.symbol)}" ${a.symbol===primary.symbol?'selected':''}>${esc(a.symbol)} /USDT · ${esc(a.name||a.symbol)}</option>`).join('')}</select><div class="chart-intervals"><button class="chip" data-charts-interval="15m">15M</button><button class="chip active" data-charts-interval="1h">1H</button><button class="chip" data-charts-interval="4h">4H</button><button class="chip" data-charts-interval="1d">1D</button></div><button class="secondary" id="chartsRefresh">↻ Refresh</button></div></div><div id="chartsChart" class="chart"><p class="muted">Loading live chart…</p></div><div class="chart-live-note"><span class="pulse"></span><b>LIVE CANDLES</b><span>Binance WebSocket · REST fallback every 5s</span></div><div id="chartsReport" class="agent-result"><span class="result-icon spin">✦</span><p>Loading live market context…</p></div><div id="chartsAiResult" class="chart-result"><span class="result-icon">✦</span><p>Run AI Chart Analysis after the live candles load.</p></div><div class="modal-actions"><button class="primary" id="chartsAiAnalyze">AI Chart Analysis</button><a class="secondary" href="#/agent">Ask AI Agent</a><button class="secondary" id="chartsOpenAsset">Open asset research</button></div></div></section>`; }
function scannerView(): string { const sorted=[...assets].sort((a,b)=>Math.abs(b.change)-Math.abs(a.change)); return `<section class="page-head"><div><span class="kicker">AI SCANNER</span><h1>Find where attention is moving.</h1><p>Signals are research prompts, not guaranteed trade calls. Ranking combines live movement with market activity.</p></div><a class="secondary" href="#/agent">Ask the Agent</a></section><section class="section two"><div class="panel"><div class="panel-head"><div><h2>Live signal board</h2><small class="muted">Sorted by absolute 24h movement · top 100</small></div><span class="status">LIVE</span>${helpButton('scanner')}</div><div class="scanner-columns"><span>Asset</span><span>24h</span><span>Volume</span><span>Signal</span></div>${sorted.slice(0,100).map((a,i)=>`<button class="scan-row" data-asset="${esc(a.symbol)}"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><b>${esc(a.symbol)}/USDT</b><small>${a.change>=0?'Momentum building':'Momentum cooling'} · ${money(a.marketCap||0)} cap</small></div><span class="${a.change>=0?'green':'red'}">${a.change>=0?'+':''}${a.change.toFixed(2)}%</span><span class="scan-volume">${money(a.volume)}</span><span class="signal ${a.change>2?'signal-hot':a.change<0?'signal-caution':''}">${a.change>2?'WATCH':a.change>=0?'NEUTRAL':'CAUTION'}</span></button>`).join('')}</div><div class="panel insight"><span class="kicker">HOW IT WORKS</span><h2>From movement to context ${helpButton('scanner')}</h2><p>CryptoPilot combines live price movement with AI reasoning so users can investigate why an asset deserves attention instead of blindly following a signal.</p><div class="score"><b>42</b><span>Market risk<br><small>Moderate</small></span></div><a class="primary wide-link" href="#/agent">Run a full market brief</a></div></section>`; }
function agentView(): string { return `<section class="page-head"><div><span class="kicker">CRYPTO AI AGENT</span><h1>Your research co-pilot.</h1><p>Ask a question. CryptoPilot fetches fresh market context, reasons through it and returns a structured brief.</p></div><span class="agent-badge">BOUNDED · NON-CUSTODIAL</span></section><section class="section agent-layout"><div class="panel agent-console"><div class="panel-title"><h2>Ask CryptoPilot</h2>${helpButton('agent')}</div><div class="agent-tools"><button class="chip" data-agent-prompt="Give me a market overview for the next few hours.">Market overview</button><button class="chip" data-agent-prompt="Which major asset has the strongest momentum and what is the main risk?">Momentum</button><button class="chip" data-agent-prompt="Compare BTC, ETH and SOL and identify the strongest setup to investigate.">Compare BTC / ETH / SOL</button></div><textarea id="agentPrompt">Analyze the current market, identify the strongest opportunity to investigate, explain the key risk, and give me a clear next step.</textarea><button class="primary agent-run" id="agentRun">Run AI Agent</button><div id="agentTimeline" class="timeline"><div><i>1</i><span>Waiting for your research question</span></div><div><i>2</i><span>Fetch fresh market context</span></div><div><i>3</i><span>Reason over trend, momentum and risk</span></div><div><i>4</i><span>Return a concise research brief</span></div></div></div><div class="panel result-panel"><span class="kicker">AGENT BRIEF</span><h2>What the agent finds</h2><div id="agentResult" class="agent-result"><span class="result-icon">✦</span><p>Run the agent to generate a fresh brief.</p></div><div class="facts"><span>Fresh context <b>Live</b></span><span>Execution <b>Disabled</b></span><span>Risk framing <b>Required</b></span></div></div></section>`; }
function screenshotFreeUses(): number { try { return Math.max(0, Math.min(3, Number(localStorage.getItem('cp_screenshot_free_uses') || 0))); } catch { return 0; } } function visionView(): string { const btc=assets.find(a=>a.symbol==='BTC')||fallback[0]; const premium=isPremiumUnlocked(); const used=screenshotFreeUses(); const remaining=Math.max(0,3-used); return `<section class="page-head"><div><span class="kicker">TRADE VISION</span><h1>Analyze your trading screen with AI.</h1><p>Upload a trading screenshot and CryptoPilot will inspect the visible setup, risk, trend and what could be improved.</p></div><span class="agent-badge">AI VISION · NO EXECUTION</span></section><section class="section two"><div class="panel upload-panel"><div class="panel-title"><div><span class="kicker">SCREENSHOT ANALYZER</span><h2>Upload a trading screenshot ${helpButton('screenshot')}</h2></div><span class="status">${premium?'PREMIUM · UNLIMITED':`${remaining} FREE LEFT`}</span></div><div class="vision-limit-note"><b>${premium?'Premium active':'3 free AI screenshot analyses'}</b><span>${premium?'Unlimited screenshot analysis is unlocked on this browser after Premium verification.':'Try the full online AI screenshot analysis three times for free. Premium unlocks continued analysis.'}</span></div><div class="dropzone" id="dropzone"><div class="upload-icon">⌁</div><b>Choose a screenshot</b><span>PNG, JPG or WEBP · max 6 MB</span><input id="chartFile" type="file" accept="image/png,image/jpeg,image/webp" /></div><div id="chartPreview" class="chart-preview hidden"></div><button class="primary wide" id="analyzeScreenshot">${premium?'Analyze screenshot with AI':remaining>0?'Analyze screenshot with AI':'Unlock more AI analyses'}</button><div id="chartResult" class="chart-result"><span class="result-icon">✦</span><p>${premium?'Premium screenshot AI is ready.':remaining>0?`${remaining} free screenshot ${remaining===1?'analysis':'analyses'} remaining.`:'Your 3 free analyses are used. Unlock Premium to continue.'}</p></div></div><div class="panel mission"><div class="mission-top"><span class="long">LIVE BTC</span><span>${money(btc.price)} · <b>${btc.change>=0?'+':''}${btc.change.toFixed(2)}%</b></span></div><h2>Trade Mission simulator</h2><p>Use the visible chart analysis as research, then build a risk-defined simulation. This never places an order.</p><div class="levels"><div><span>Entry</span><b>${money(btc.price*.995)}</b></div><div><span>Stop</span><b>${money(btc.price*.975)}</b></div><div><span>Take profit 1</span><b>${money(btc.price*1.025)}</b></div><div><span>Take profit 2</span><b>${money(btc.price*1.055)}</b></div></div><button class="secondary wide" id="missionAnalyze">Ask Agent to review mission</button></div></section>`; }
function portfolioView(): string { return `<section class="page-head"><div><span class="kicker">PORTFOLIO</span><h1>Track what matters.</h1><p>Read-only tracking with local holdings, live prices, cost basis, P&L and a browser watchlist. CryptoPilot never holds or trades your funds.</p><div class="privacy-note"><b>Private by design:</b> holdings and watchlists stay in this browser in the current release.</div></div>${helpButton('portfolio')}</section><section class="section portfolio-grid"><div class="panel"><div class="panel-title"><div><span class="kicker">ADD HOLDING</span><h2>Portfolio position</h2></div></div><div class="form-grid"><select id="holdingAsset" class="form-input">${assets.slice(0,20).map(a=>`<option value="${esc(a.symbol)}">${esc(a.symbol)} · ${esc(a.name||a.symbol)}</option>`).join('')}</select><input id="holdingQty" class="form-input" type="number" min="0" step="any" placeholder="Quantity" /><input id="holdingCost" class="form-input" type="number" min="0" step="any" placeholder="Average cost (USD)" /></div><button class="primary wide" id="saveHolding">Add / update holding</button><p id="holdingMsg" class="muted"></p></div><div class="panel"><span class="kicker">PORTFOLIO SNAPSHOT</span><h2 id="portfolioTotal">$0</h2><div id="portfolioRows">No holdings yet.</div></div><div class="panel"><div class="panel-title"><div><span class="kicker">WATCHLIST</span><h2>Saved research</h2></div><span class="status">LOCAL</span></div><div id="watchlist">No assets saved yet.</div><button class="secondary wide" id="addWatch">Add BTC to watchlist</button></div></section>`; }
function alertsView(): string { return `<section class="page-head"><div><span class="kicker">ALERTS</span><h1>Stop staring at charts.</h1><p>Create browser alerts from a live baseline. When the chosen asset moves by your threshold, CryptoPilot can notify you while this tab is open.</p><div class="privacy-note"><b>Browser alerts:</b> local monitoring requires this tab to remain open.</div></div>${helpButton('alerts')}</section><section class="section two"><div class="panel alert-builder"><span class="kicker">NEW ALERT</span><h2>Set a movement threshold</h2><select id="alertAsset" class="form-input">${assets.slice(0,20).map(a=>`<option value="${esc(a.symbol)}">${esc(a.symbol)} · ${esc(a.name||a.symbol)}</option>`).join('')}</select><input id="alertPct" class="form-input" type="number" min="0.1" step="0.1" value="5" /><button class="primary wide" id="saveAlert">Save live alert</button><p id="alertMsg" class="muted"></p></div><div class="panel"><span class="kicker">ACTIVE</span><h2>Your alerts</h2><div id="alertsList">No alerts created yet.</div></div></section>`; }
function qaView(): string { return `<section class="page-head"><div><span class="kicker">AUTONOMOUS QA</span><h1>CryptoPilot checks itself.</h1><p>The QA Agent inspects live market coverage, candles, discovery feeds and AI health. It reports concrete failures and prioritized improvements without executing trades or changing code silently.</p></div><span class="agent-badge">SELF-CHECK · SAFE</span></section><section class="section qa-grid"><div class="panel"><div class="panel-title"><div><span class="kicker">DETERMINISTIC CHECKS</span><h2>System health</h2></div><span id="qaOverall" class="status">READY</span></div><div id="qaChecks" class="qa-checks"><p class="muted">Run the health audit.</p></div><button class="primary wide" id="qaRun">Run full QA audit</button></div><div class="panel"><div class="panel-title"><div><span class="kicker">AI DIAGNOSIS</span><h2>Improvement Agent</h2></div><span class="status">BOUNDED</span></div><div id="qaAgentResult" class="agent-result"><span class="result-icon">✦</span><p>Run the autonomous agent to inspect the product and prioritize fixes.</p></div><button class="secondary wide" id="qaAgentRun">Run AI improvement audit</button><p class="muted">The agent is intentionally bounded: it can inspect and diagnose, but deployment changes remain under controlled release.</p></div></section>`; }
function premiumView(): string { return `<section class="page-head"><div><span class="kicker">CRYPTOPILOT PREMIUM</span><h1>Advanced intelligence without the clutter.</h1><p>One simple 30-day plan. Payment is handled in a private checkout flow; your wallet address is not exposed on the main page.</p><div class="premium-proof"><span>✓ Live market research</span><span>✓ AI interpretation</span><span>✓ Non-custodial</span></div></div><div class="price-badge"><strong>3</strong><span>USDT<br>30 days</span></div></section><section class="section premium-grid"><div class="panel benefits"><h2>What you unlock</h2><div class="benefit"><b>AI Agent missions</b><span>Fresh context + structured research briefs</span></div><div class="benefit"><b>Advanced scanner</b><span>Prioritized movement and risk context</span></div><div class="benefit"><b>Trade Vision</b><span>Screenshot AI + risk-defined simulation workflows</span></div><div class="benefit"><b>Alerts & watchlists</b><span>Monitor the assets that matter to you</span></div></div><div class="checkout-card">${helpButton('payment')}<span class="kicker">30-DAY ACCESS</span><h2>Premium</h2><div class="checkout-price"><strong>3</strong><span>USDT</span></div><p>USDT on TRON (TRC20). Non-custodial payment.</p><button class="primary wide" id="checkoutBtn">Continue to secure checkout</button><small>Wallet details appear only after you confirm the plan.</small></div></section>`; }
function render(): void { stopLiveChart(); const views: Record<Route,()=>string>={home:homeView,markets:marketsView,charts:chartsView,scanner:scannerView,agent:agentView,qa:qaView,vision:visionView,premium:premiumView,portfolio:portfolioView,alerts:alertsView}; shell(views[route]()); bindInteractions(); if(route==='markets')bindMarketTools(); if(route==='charts')bindCharts(); if(route==='portfolio')bindPortfolio(); if(route==='alerts')bindAlerts(); if(route==='qa')bindQa(); }
function bindCharts(): void { bindChartViewportInteractions(); const symbolSelect=document.getElementById('chartsAsset') as HTMLSelectElement|null; const symbol=()=>symbolSelect?.value||assets[0]?.symbol||'BTC'; const setActive=(interval:string)=>document.querySelectorAll<HTMLButtonElement>('[data-charts-interval]').forEach(b=>b.classList.toggle('active',(b.dataset.chartsInterval||'1h')===interval)); const load=(interval:string)=>{setActive(interval);void loadChartsPage(symbol(),interval);}; symbolSelect?.addEventListener('change',()=>load('1h')); document.querySelectorAll<HTMLButtonElement>('[data-charts-interval]').forEach(b=>b.addEventListener('click',()=>load(b.dataset.chartsInterval||'1h'))); document.getElementById('chartsRefresh')?.addEventListener('click',()=>load(liveChartInterval)); document.getElementById('chartsAiAnalyze')?.addEventListener('click',()=>void analyzeChartsPage(symbol(),liveChartInterval)); document.getElementById('chartsOpenAsset')?.addEventListener('click',()=>openAsset(symbol())); setActive('1h'); void loadChartsPage(symbol(),'1h'); }
async function loadChartsPage(symbol:string, interval:string):Promise<void>{ const chart=document.getElementById('chartsChart'); const report=document.getElementById('chartsReport'); if(!chart||!report)return; stopLiveChart(); liveChartSymbol=symbol; liveChartInterval=interval; const title=document.getElementById('chartsSymbol'); if(title)title.textContent=symbol; chart.innerHTML='<p class="muted">Loading live chart…</p>'; report.innerHTML='<span class="result-icon spin">✦</span><p>Loading live market context…</p>'; try { let data:any=null; try { const response=await api.get(`/api/asset-detail?symbol=${encodeURIComponent(symbol)}&interval=${encodeURIComponent(interval)}&limit=240`); data=response.data; } catch { data=null; } let candles=Array.isArray(data?.candles)?data.candles:[]; if(!candles.length) candles=await fetchClientCandles(symbol,interval,240); if(!candles.length)throw new Error('No chart data'); chartCandles=candles.sort((x:any,y:any)=>Number(x.time)-Number(y.time)); chartViewportSize=Math.min(90,Math.max(40,chartCandles.length)); chartViewportStart=Math.max(0,chartCandles.length-chartViewportSize); chartHistoryLoading=false; const a=data?.asset||{}; const fallbackPrice=Number(candles[candles.length-1]?.close)||0; const price=Number(a.price)||fallbackPrice; const priceEl=document.getElementById('chartsPrice'); if(priceEl)priceEl.textContent=money(price); drawChartsPage(); report.innerHTML=`<span class="result-icon">✦</span><p><b>${esc(symbol)} live report</b><br>Price: ${money(price)} · 24h: ${Number.isFinite(Number(a.change))?`${Number(a.change)>=0?'+':''}${Number(a.change).toFixed(2)}%`:'Live'}<br>24h high: ${money(Number(a.high)||Math.max(...candles.map(c=>c.high)))} · low: ${money(Number(a.low)||Math.min(...candles.map(c=>c.low)))}<br>Volume: ${money(Number(a.volume)||0)}<br><span class="muted">Live Binance data with app API and direct browser REST fallback. Research context only.</span></p>`; startLiveChart(symbol,interval); } catch { chart.innerHTML='<p class="error-text">Live chart is temporarily unavailable. Use Refresh to retry.</p>'; report.innerHTML='<span class="result-icon">!</span><p>Chart data could not be loaded. Check the connection and retry.</p>'; } }
function drawChartsPage():void { const chart=document.getElementById('chartsChart'); if(!chart||!chartCandles.length)return; const total=chartCandles.length; chartViewportSize=Math.min(Math.max(30,chartViewportSize),total); chartViewportStart=Math.max(0,Math.min(chartViewportStart,Math.max(0,total-chartViewportSize))); const end=chartViewportStart+chartViewportSize; const visible=chartCandles.slice(chartViewportStart,end); const width=900,height=390,left=18,right=78,top=18,bottom=42,min=Math.min(...visible.map(c=>c.low)),max=Math.max(...visible.map(c=>c.high)),range=max-min||Math.max(1,max*.01),step=(width-left-right)/Math.max(1,visible.length-1),bodyWidth=Math.max(3,Math.min(13,step*.62)),maxVolume=Math.max(...chartCandles.map(c=>c.volume||0),1),y=(price:number)=>top+(1-(price-min)/range)*(height-top-bottom),x=(i:number)=>left+i*step; const grid=[.2,.4,.6,.8].map(p=>`<line x1="${left}" y1="${top+p*(height-top-bottom)}" x2="${width-right}" y2="${top+p*(height-top-bottom)}" stroke="#203248"/>`).join(''); const candles=visible.map((c,i)=>{const xx=x(i),up=c.close>=c.open,stroke=up?'#43d6a2':'#ff6b7a',bodyTop=Math.min(y(c.open),y(c.close)),bodyHeight=Math.max(1.5,Math.abs(y(c.close)-y(c.open)));const volumeHeight=Math.max(2,((c.volume||0)/maxVolume)*42);return `<line x1="${xx}" y1="${y(c.high)}" x2="${xx}" y2="${y(c.low)}" stroke="${stroke}" stroke-width="1.5"/><rect x="${xx-bodyWidth/2}" y="${bodyTop}" width="${bodyWidth}" height="${bodyHeight}" rx="1" fill="${stroke}"/><rect x="${xx-bodyWidth/2}" y="${height-bottom-volumeHeight}" width="${bodyWidth}" height="${volumeHeight}" rx="1" fill="${stroke}" opacity=".18"/>`;}).join(''); const last=visible[visible.length-1]; const isLive=end>=total; const status=chartHistoryLoading?'LOADING HISTORY…':isLive?'LIVE':'HISTORICAL'; chart.innerHTML=`<div class="chart-viewport-toolbar"><button class="chip" data-chart-nav="older">← Older</button><button class="chip" data-chart-nav="newer">Newer →</button><button class="chip ${isLive?'active':''}" data-chart-nav="live">● LIVE</button><button class="chip" data-chart-nav="zoom-out">−</button><button class="chip" data-chart-nav="zoom-in">+</button><span class="chart-viewport-status">${status} · ${chartViewportStart+1}-${end} / ${total}</span></div><div class="terminal-chart-wrap" style="touch-action:none;cursor:grab"><svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Live ${esc(liveChartSymbol)} candlestick chart">${grid}${candles}<line x1="${left}" y1="${y(last.close)}" x2="${width-right}" y2="${y(last.close)}" stroke="#6fddff" stroke-width="1" stroke-dasharray="5 5"/></svg><div class="chart-axis"><span>Low ${money(min)}</span><b>Last ${money(last.close)}</b><span>High ${money(max)}</span></div></div><p class="muted chart-status">${esc(liveChartSymbol)}/USDT · ${esc(liveChartInterval)} · ${status} · drag to pan · wheel to zoom · ${new Date(last.time).toLocaleString()} · WebSocket ${liveChartSocket?.readyState===WebSocket.OPEN?'LIVE':'reconnecting'} · REST fallback</p>`; }
async function analyzeChartsPage(symbol:string, interval:string):Promise<void>{const result=document.getElementById('chartsAiResult');const button=document.getElementById('chartsAiAnalyze') as HTMLButtonElement|null;if(!result||!button)return;button.disabled=true;button.textContent='AI analyzing…';result.innerHTML='<span class="result-icon spin">✦</span><p>Calculating fresh indicators and asking CryptoPilot AI…</p>';try{const {data}=await api.post('/api/ai/asset-chart-analysis',{symbol,interval});if(!data?.ok)throw new Error(String(data?.message||'Analysis unavailable'));const c=data.context||{};result.innerHTML=`<span class="result-icon">✦</span><p><b>AI technical analysis · ${esc(symbol)}/USDT · ${esc(interval)}</b><br><span class="muted">RSI 14: ${Number(c.rsi14).toFixed(1)} · EMA20: ${money(Number(c.ema20))} · EMA50: ${money(Number(c.ema50))} · Support: ${money(Number(c.support))} · Resistance: ${money(Number(c.resistance))} · Trend: ${esc(c.trend)}</span><br><br>${esc(data.text||'No readable AI analysis returned.').replace(/\\n/g,'<br>')}</p>`;}catch{result.innerHTML='<span class="result-icon">!</span><p>AI chart analysis is temporarily unavailable. Retry the analysis.</p>';}button.disabled=false;button.textContent='AI Chart Analysis'; }
async function bindQa(): Promise<void> { const checks=document.getElementById('qaChecks'); const overall=document.getElementById('qaOverall'); document.getElementById('qaRun')?.addEventListener('click',async()=>{if(checks)checks.innerHTML='<p class="muted">Running deterministic checks…</p>';if(overall)overall.textContent='RUNNING';try{const {data}=await api.get('/api/qa/status');if(overall)overall.textContent=data.ok?'ALL SYSTEMS HEALTHY':'ATTENTION NEEDED';if(checks)checks.innerHTML=(data.checks||[]).map((c:{name:string;status:string;detail:string;latencyMs:number})=>`<div class="qa-row"><b>${esc(c.name)}</b><span class="${c.status==='PASS'?'green':'red'}">${esc(c.status)}</span><small>${esc(c.detail)} · ${c.latencyMs}ms</small></div>`).join('');}catch{if(overall)overall.textContent='CHECK FAILED';if(checks)checks.innerHTML='<p class="error-text">QA service unavailable. Retry shortly.</p>';}});document.getElementById('qaAgentRun')?.addEventListener('click',async()=>{const out=document.getElementById('qaAgentResult');const b=document.getElementById('qaAgentRun') as HTMLButtonElement|null;if(!out||!b)return;b.disabled=true;b.textContent='Agent auditing…';out.innerHTML='<span class="result-icon spin">✦</span><p>Inspecting market, charts, discovery and AI…</p>';try{const {data}=await api.post('/api/ai/qa-agent',{});if(!data?.ok)throw new Error('QA agent unavailable');const d=data.data||{};const findings=Array.isArray(d.findings)?d.findings.map((x:string)=>`<li>${esc(x)}</li>`).join(''):'<li>No structured findings returned.</li>';const actions=Array.isArray(d.actions)?d.actions.map((x:string)=>`<li>${esc(x)}</li>`).join(''):'<li>No structured actions returned.</li>';out.innerHTML=`<span class="result-icon">✦</span><div><b>${esc(d.overall||'QA diagnosis')}</b><p>${esc(d.summary||data.text||'Audit completed.')}</p><b>Findings</b><ul>${findings}</ul><b>Priority actions</b><ol>${actions}</ol><small class="muted">${esc(data.updatedAt||'')}</small></div>`;}catch{out.innerHTML='<span class="result-icon">!</span><p>Autonomous QA agent is temporarily unavailable. Run the deterministic audit instead.</p>';}b.disabled=false;b.textContent='Run AI improvement audit';}); }
function bindInteractions(): void { document.querySelectorAll<HTMLElement>('[data-asset]').forEach(el=>{el.addEventListener('click',()=>openAsset(el.dataset.asset||'BTC'));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openAsset(el.dataset.asset||'BTC');}});}); document.querySelector('[data-home-market-page="prev"]')?.addEventListener('click',()=>{if(homeMarketPage>1){homeMarketPage--;render();}}); document.querySelector('[data-home-market-page="next"]')?.addEventListener('click',()=>{const ranked=assets.filter(a=>a.price>0);if(homeMarketPage<Math.max(1,Math.ceil(Math.min(500,ranked.length)/50))){homeMarketPage++;render();}}); if(route==='home'||route==='markets')void hydrateMoverSparklines(); document.getElementById('refreshMarkets')?.addEventListener('click',()=>void loadMarket(true)); document.getElementById('checkoutBtn')?.addEventListener('click',openCheckout); document.getElementById('agentRun')?.addEventListener('click',()=>void runAgent()); document.querySelectorAll<HTMLButtonElement>('[data-agent-prompt]').forEach(b=>b.addEventListener('click',()=>{(document.getElementById('agentPrompt') as HTMLTextAreaElement).value=b.dataset.agentPrompt||'';})); document.getElementById('missionAnalyze')?.addEventListener('click',()=>{location.hash='#/agent';window.setTimeout(()=>{const input=document.getElementById('agentPrompt') as HTMLTextAreaElement;if(input){input.value='Review the current BTC Trade Vision mission. Challenge the entry, stop, targets and main invalidation risk.';void runAgent();}},120);}); document.getElementById('chartFile')?.addEventListener('change',()=>void prepareChartFile()); document.getElementById('analyzeScreenshot')?.addEventListener('click',()=>void analyzeScreenshot()); }
function bindHelp(): void { document.querySelectorAll<HTMLButtonElement>('[data-help]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openHelp(b.dataset.help||'general');})); }
function openHelp(topic:string):void{const map:Record<string,string>={risk:'Market Risk Score summarizes current market conditions. Green/low means calmer conditions; higher scores mean more volatility and uncertainty. The score is a research aid, not a prediction.',pulse:'These cards show live market movement. Tap an asset to open its research view and then send a focused question to the AI Agent.',gainers:'Top Gainers shows assets with the strongest positive 24h movement in the live Binance feed. A fast rise can also mean higher risk.',losers:'Top Losers shows assets with the largest negative 24h movement in the live Binance feed. A drop is not automatically a buying opportunity.',scanner:'AI Scanner ranks attention signals. It is designed to tell you what deserves research, not to promise a winning trade.',agent:'AI Agent fetches fresh market context, reasons over it and returns a structured research brief. It cannot place trades.',screenshot:'Take a screenshot of your TradingView or exchange chart, upload it in Trade Vision, and CryptoPilot AI will inspect visible trend, support/resistance, momentum, risk and what you could improve. You get 3 free online analyses; Premium removes the limit.',portfolio:'Portfolio is read-only by design. CryptoPilot does not hold funds or execute trades.',alerts:'Alerts are for monitoring and research. The current browser foundation stores the rule locally; server notifications can be added in the account layer.',payment:'Premium uses a private checkout. The receiving wallet is intentionally hidden until you confirm the plan, then you can copy it and verify the TRON transaction.',asset:'Click a market card to inspect price, movement, risk posture and jump into AI research.'};const text=map[topic.split(':')[0]]||map.asset;modal(`<div class="modal-head"><div><span class="kicker">QUICK GUIDE</span><h2>How this works</h2></div><button class="close" id="modalClose">×</button></div><div class="guide-icon">?</div><p class="modal-copy">${esc(text)}</p><button class="primary wide" id="modalCloseAction">Got it</button>`);document.getElementById('modalCloseAction')?.addEventListener('click',()=>document.getElementById('modalRoot')?.remove());}
function modal(inner:string):void{const old=document.getElementById('modalRoot');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modalRoot"><div class="modal" role="dialog" aria-modal="true">${inner}</div></div>`);const close=()=>document.getElementById('modalRoot')?.remove();document.getElementById('modalClose')?.addEventListener('click',close);document.getElementById('modalRoot')?.addEventListener('click',e=>{if(e.target===document.getElementById('modalRoot'))close();});}
let liveChartSocket: WebSocket | null = null;
let liveChartPollTimer: number | null = null;
let liveChartReconnectTimer: number | null = null;
let marketRefreshInFlight = false;
let liveChartSymbol = '';
let liveChartInterval = '1h';
let chartViewportStart = 0;
let chartViewportSize = 80;
let chartHistoryLoading = false;
let chartDragStartX = 0;
let chartDragStartIndex = 0;

function stopLiveChart(): void {
  if (liveChartSocket) liveChartSocket.close();
  liveChartSocket = null;
  if (liveChartPollTimer !== null) window.clearInterval(liveChartPollTimer);
  liveChartPollTimer = null;
  if (liveChartReconnectTimer !== null) window.clearTimeout(liveChartReconnectTimer);
  liveChartReconnectTimer = null;
}

function applyLiveCandle(candle: {time:number;open:number;high:number;low:number;close:number;volume:number}): void {
  const wasFollowingLive = chartCandles.length === 0 || chartViewportStart + chartViewportSize >= chartCandles.length - 1;
  const last = chartCandles[chartCandles.length - 1];
  if (last && last.time === candle.time) chartCandles[chartCandles.length - 1] = candle;
  else chartCandles = [...chartCandles, candle];
  if (wasFollowingLive) chartViewportStart = Math.max(0, chartCandles.length - chartViewportSize);
  drawLiveChart();
  const price = document.getElementById('assetHeroPrice');
  if (price) price.textContent = money(candle.close);
  const chartsPrice = document.getElementById('chartsPrice');
  if (chartsPrice) chartsPrice.textContent = money(candle.close);
  if (document.getElementById('chartsChart')) drawChartsPage();
}

async function fetchClientCandles(symbol: string, interval: string, limit = 80, endTime?: number): Promise<Array<{time:number;open:number;high:number;low:number;close:number;volume:number}>> { const response = await fetch(`https://api.binance.com/api/v3/klines?symbol=${encodeURIComponent(symbol.toUpperCase())}USDT&interval=${encodeURIComponent(interval)}&limit=${Math.min(1000,Math.max(1,limit))}${Number.isFinite(endTime)?`&endTime=${Math.floor(Number(endTime))}`:''}`, { cache: 'no-store' }); if (!response.ok) throw new Error(`Binance candles ${response.status}`); const rows = await response.json() as Array<[number,string,string,string,string,string]>; return rows.map(row => ({ time: Number(row[0]), open: Number(row[1]), high: Number(row[2]), low: Number(row[3]), close: Number(row[4]), volume: Number(row[5]) })).filter(c => Number.isFinite(c.close) && c.close > 0); }

async function refreshLiveChartFromApi(): Promise<void> {
  if (!liveChartSymbol) return;
  const symbol = liveChartSymbol;
  const interval = liveChartInterval;
  try {
    let data: any = null;
    try { const response = await api.get(`/api/asset-detail?symbol=${encodeURIComponent(symbol)}&interval=${encodeURIComponent(interval)}&limit=240`); data = response.data; } catch { data = null; }
    if (liveChartSymbol !== symbol || liveChartInterval !== interval) return;
    let candles = Array.isArray(data?.candles) ? data.candles : [];
    if (!candles.length) candles = await fetchClientCandles(symbol, interval, 240);
    if (!candles.length) return;
    chartCandles = candles;
    if (document.getElementById('assetChart')) drawLiveChart();
    if (document.getElementById('chartsChart')) drawChartsPage();
    const price = document.getElementById('assetHeroPrice');
    const chartsPrice = document.getElementById('chartsPrice');
    const change = document.getElementById('assetHeroChange');
    if (price && data.asset?.price) price.textContent = money(Number(data.asset.price));
    if (chartsPrice && data.asset?.price) chartsPrice.textContent = money(Number(data.asset.price));
    if (change && Number.isFinite(Number(data.asset?.change))) {
      const value = Number(data.asset.change);
      change.textContent = `${value >= 0 ? '+' : ''}${value.toFixed(2)}% 24h`;
      change.className = value >= 0 ? 'green' : 'red';
    }
  } catch { /* WebSocket remains the primary stream; polling is a fallback. */ }
}

async function loadOlderChartHistory(): Promise<void> { if (chartHistoryLoading || !liveChartSymbol || !chartCandles.length) return; chartHistoryLoading=true; drawChartsPage(); try { const older=await fetchClientCandles(liveChartSymbol,liveChartInterval,240,chartCandles[0].time-1); const existing=new Set(chartCandles.map(c=>c.time)); const fresh=older.filter(c=>!existing.has(c.time)); if(fresh.length){chartCandles=[...fresh,...chartCandles].sort((a,b)=>a.time-b.time);chartViewportStart+=fresh.length;} } catch {} finally { chartHistoryLoading=false; drawChartsPage(); } }
function bindChartViewportInteractions(): void { const chart=document.getElementById('chartsChart'); if(!chart||chart.dataset.viewportBound==='1')return; chart.dataset.viewportBound='1'; let dragging=false,startX=0,startViewport=0; chart.addEventListener('pointerdown',e=>{const target=e.target as HTMLElement;if(target.closest('[data-chart-nav]'))return;dragging=true;startX=e.clientX;startViewport=chartViewportStart;chart.setPointerCapture?.(e.pointerId);}); chart.addEventListener('pointermove',e=>{if(!dragging)return;const wrap=chart.querySelector<HTMLElement>('.terminal-chart-wrap');const width=wrap?.clientWidth||900;const delta=Math.round((startX-e.clientX)/(Math.max(4,width/Math.max(1,chartViewportSize-1))));chartViewportStart=Math.max(0,Math.min(startViewport+delta,Math.max(0,chartCandles.length-chartViewportSize)));drawChartsPage();if(chartViewportStart===0&&delta>0)void loadOlderChartHistory();}); chart.addEventListener('pointerup',()=>{dragging=false;}); chart.addEventListener('pointercancel',()=>{dragging=false;}); chart.addEventListener('wheel',e=>{e.preventDefault();const oldSize=chartViewportSize;const next=e.deltaY<0?Math.max(30,Math.floor(oldSize*.8)):Math.min(Math.max(30,chartCandles.length),Math.ceil(oldSize*1.25));if(next===oldSize)return;const wasLive=chartViewportStart+oldSize>=chartCandles.length-1;chartViewportSize=next;chartViewportStart=wasLive?Math.max(0,chartCandles.length-next):Math.min(chartViewportStart,Math.max(0,chartCandles.length-next));drawChartsPage();},{passive:false}); chart.addEventListener('click',e=>{const button=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-chart-nav]');if(!button)return;const action=button.dataset.chartNav;const step=Math.max(10,Math.floor(chartViewportSize*.75));if(action==='older'){if(chartViewportStart===0){void loadOlderChartHistory();return;}chartViewportStart=Math.max(0,chartViewportStart-step);}else if(action==='newer'){chartViewportStart=Math.min(Math.max(0,chartCandles.length-chartViewportSize),chartViewportStart+step);}else if(action==='live'){chartViewportStart=Math.max(0,chartCandles.length-chartViewportSize);}else if(action==='zoom-in'){chartViewportSize=Math.max(30,Math.floor(chartViewportSize*.8));}else if(action==='zoom-out'){chartViewportSize=Math.min(Math.max(30,chartCandles.length),Math.ceil(chartViewportSize*1.25));}chartViewportStart=Math.min(chartViewportStart,Math.max(0,chartCandles.length-chartViewportSize));drawChartsPage();}); }
function startLiveChart(symbol: string, interval: string): void {
  stopLiveChart();
  liveChartSymbol = symbol;
  liveChartInterval = interval;
  const url = `wss://stream.binance.com:443/ws/${symbol.toLowerCase()}usdt@kline_${interval}`;
  const connect = (): void => {
    if (liveChartSymbol !== symbol || liveChartInterval !== interval) return;
    try {
      liveChartSocket = new WebSocket(url);
      liveChartSocket.onmessage = event => {
        try {
          const msg = JSON.parse(event.data) as { k?: { t:number; o:string; h:string; l:string; c:string; v:string } };
          const k = msg.k;
          if (!k) return;
          applyLiveCandle({time:Number(k.t), open:Number(k.o), high:Number(k.h), low:Number(k.l), close:Number(k.c), volume:Number(k.v)});
        } catch { /* ignore malformed stream messages */ }
      };
      liveChartSocket.onclose = () => {
        liveChartSocket = null;
        if (liveChartSymbol === symbol && liveChartInterval === interval && liveChartReconnectTimer === null) {
          liveChartReconnectTimer = window.setTimeout(() => { liveChartReconnectTimer = null; connect(); }, 3000);
        }
      };
      liveChartSocket.onerror = () => { liveChartSocket?.close(); };
    } catch { liveChartSocket = null; }
  };
  connect();
  liveChartPollTimer = window.setInterval(() => void refreshLiveChartFromApi(), 5000);
  void refreshLiveChartFromApi();
}

let chartCandles: Array<{time:number;open:number;high:number;low:number;close:number;volume:number}> = [];
function drawLiveChart(): void {
  const chart = document.getElementById('assetChart');
  if (!chart || !chartCandles.length) return;
  const width = 1200;
  const height = 520;
  const left = 22;
  const right = 76;
  const top = 20;
  const bottom = 42;
  const volumeHeight = 88;
  const priceBottom = height - bottom - volumeHeight;
  const min = Math.min(...chartCandles.map(c => c.low));
  const max = Math.max(...chartCandles.map(c => c.high));
  const range = max - min || Math.max(1, max * 0.01);
  const step = (width - left - right) / Math.max(1, chartCandles.length - 1);
  const bodyWidth = Math.max(4, Math.min(18, step * 0.68));
  const y = (price:number) => top + (1 - (price - min) / range) * (priceBottom - top);
  const x = (index:number) => left + index * step;
  const maxVolume = Math.max(...chartCandles.map(c => c.volume || 0), 1);
  const grid = [0.2,0.4,0.6,0.8].map(p => {
    const yy = top + p * (priceBottom - top);
    return `<line x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}" stroke="#203248" stroke-width="1"/><text x="${width-right+8}" y="${yy+3}" fill="#61788e" font-size="10">${esc(money(max-(max-min)*p))}</text>`;
  }).join('');
  const candles = chartCandles.map((c,i) => {
    const xx = x(i);
    const up = c.close >= c.open;
    const stroke = up ? '#43d6a2' : '#ff6b7a';
    const wick = `<line x1="${xx}" y1="${y(c.high)}" x2="${xx}" y2="${y(c.low)}" stroke="${stroke}" stroke-width="2"/>`;
    const bodyTop = Math.min(y(c.open), y(c.close));
    const bodyHeight = Math.max(2, Math.abs(y(c.close) - y(c.open)));
    const body = `<rect x="${xx-bodyWidth/2}" y="${bodyTop}" width="${bodyWidth}" height="${bodyHeight}" rx="1.5" fill="${stroke}"/>`;
    const vh = Math.max(2, ((c.volume || 0) / maxVolume) * volumeHeight);
    const volume = `<rect x="${xx-bodyWidth/2}" y="${priceBottom+volumeHeight-vh}" width="${bodyWidth}" height="${vh}" rx="1" fill="${stroke}" opacity=".24"/>`;
    return wick + body + volume;
  }).join('');
  const last = chartCandles[chartCandles.length - 1];
  const liveLine = `<line x1="${left}" y1="${y(last.close)}" x2="${width-right}" y2="${y(last.close)}" stroke="#6fddff" stroke-width="1.5" stroke-dasharray="6 5"/><text x="${width-right+8}" y="${y(last.close)+4}" fill="#6fddff" font-size="11" font-weight="700">${esc(money(last.close))}</text>`;
  const timeLabels = chartCandles.filter((_,i) => i % Math.max(1, Math.floor(chartCandles.length / 6)) === 0).map((c,i) => {
    const originalIndex = chartCandles.indexOf(c);
    return `<text x="${x(originalIndex)}" y="${height-10}" text-anchor="middle" fill="#61788e" font-size="10">${esc(new Date(c.time).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))}</text>`;
  }).join('');
  chart.innerHTML = `<div class="terminal-chart-wrap"><svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Live ${esc(liveChartSymbol)} candlestick and volume chart">${grid}<line x1="${left}" y1="${priceBottom}" x2="${width-right}" y2="${priceBottom}" stroke="#263b50"/>${candles}${liveLine}${timeLabels}</svg><div class="chart-axis"><span>Low ${money(min)}</span><b>Last ${money(last.close)}</b><span>High ${money(max)}</span></div></div><p class="muted chart-status">${esc(liveChartSymbol)}/USDT · ${esc(liveChartInterval)} · ${chartCandles.length} candles · last ${new Date(last.time).toLocaleString()} · WebSocket ${liveChartSocket?.readyState===WebSocket.OPEN?'LIVE':'reconnecting'} · REST fallback</p>`;
}

async function loadAssetDetail(symbol:string, interval:string):Promise<void>{const chart=document.getElementById('assetChart');const report=document.getElementById('assetReport');if(!chart||!report)return;stopLiveChart();liveChartSymbol=symbol;liveChartInterval=interval;chart.innerHTML='<p class="muted">Loading live chart…</p>';report.innerHTML='<span class="result-icon spin">✦</span><p>Loading live market data…</p>';const requestSymbol=symbol;const requestInterval=interval;try{let data:any=null;try{const response=await api.get(`/api/asset-detail?symbol=${encodeURIComponent(symbol)}&interval=${encodeURIComponent(interval)}&limit=240`);data=response.data;}catch{data=null;}if(liveChartSymbol!==requestSymbol||liveChartInterval!==requestInterval)return;let candles=Array.isArray(data?.candles)?data.candles:[];if(!candles.length)candles=await fetchClientCandles(symbol,interval,80);if(!candles.length)throw new Error('No chart data');chartCandles=candles;drawLiveChart();const a=data?.asset||{};const fallbackPrice=Number(candles[candles.length-1]?.close)||0;const priceValue=Number(a.price)||fallbackPrice;const price=document.getElementById('assetHeroPrice');const change=document.getElementById('assetHeroChange');if(price&&priceValue)price.textContent=money(priceValue);if(change&&Number.isFinite(Number(a.change))){const value=Number(a.change);change.textContent=`${value>=0?'+':''}${value.toFixed(2)}% 24h`;change.className=value>=0?'green':'red';}const high=Number(a.high)||Math.max(...candles.map(c=>c.high)); const low=Number(a.low)||Math.min(...candles.map(c=>c.low)); const highEl=document.getElementById('assetHigh'); const lowEl=document.getElementById('assetLow'); const tradesEl=document.getElementById('assetTrades'); const fundingEl=document.getElementById('assetFunding'); const oiEl=document.getElementById('assetOi'); const lsEl=document.getElementById('assetLs'); const bookEl=document.getElementById('assetBook'); if(highEl)highEl.textContent=money(high); if(lowEl)lowEl.textContent=money(low); if(tradesEl)tradesEl.textContent=Number(a.trades||0).toLocaleString(); if(fundingEl)fundingEl.textContent=Number(a.fundingRate)?`${Number(a.fundingRate).toFixed(4)}%`:'N/A'; if(oiEl)oiEl.textContent=Number(a.openInterest)?money(Number(a.openInterest)):'N/A'; if(lsEl)lsEl.textContent=Number(a.longShortRatio)?Number(a.longShortRatio).toFixed(2):'N/A'; if(bookEl)bookEl.textContent=Number(a.bidAskImbalance)?`${Number(a.bidAskImbalance)>0?'+':''}${Number(a.bidAskImbalance).toFixed(1)}%`:'N/A'; report.innerHTML=`<span class="result-icon">✦</span><p><b>${esc(symbol)} live trader context</b><br>Price: ${money(priceValue)} · 24h: ${Number.isFinite(Number(a.change))?`${Number(a.change)>=0?'+':''}${Number(a.change).toFixed(2)}%`:'Live'} · Range: ${money(low)} → ${money(high)}<br>Volume: ${money(Number(a.volume)||0)} · Funding: ${Number(a.fundingRate)?`${Number(a.fundingRate).toFixed(4)}%`:'N/A'} · OI: ${Number(a.openInterest)?money(Number(a.openInterest)):'N/A'} · L/S: ${Number(a.longShortRatio)?Number(a.longShortRatio).toFixed(2):'N/A'}<br><span class="muted">Trader context combines price/volume with funding, open interest, positioning and order-book pressure when derivatives data is available. Premium adds AI interpretation of RSI/EMA, support/resistance, trend, risk and a structured research brief.</span></p>`;startLiveChart(symbol,interval);}catch{if(liveChartSymbol!==requestSymbol||liveChartInterval!==requestInterval)return;chart.innerHTML='<p class="error-text">Live chart is temporarily unavailable. Use Refresh to retry.</p>';report.innerHTML='<span class="result-icon">!</span><p>Live chart could not be loaded. Check the connection and retry.</p>';}}
