function openMobileMenu():void{modal(`<div class="modal-head"><div><span class="kicker">NAVIGATION</span><h2>CryptoPilot</h2></div><button class="close" id="modalClose">×</button></div><div class="mobile-links">${['home','markets','charts','scanner','agent','qa','vision','portfolio','alerts','premium'].map(key=>`<a class="mobile-link" href="#/${key}" data-mobile-link>${key==='home'?'Overview':key.replace(/^./,c=>c.toUpperCase())}</a>`).join('')}`);document.querySelectorAll<HTMLElement>('[data-mobile-link]').forEach(el=>el.addEventListener('click',()=>document.getElementById('modalRoot')?.remove()));}
async function openSignin():Promise<void>{if(auth.isSignedIn()){try{await auth.signOut();await syncAuthButton();}catch{modal(`<div class="modal-head"><div><span class="kicker">ACCOUNT</span><h2>Sign out</h2></div><button class="close" id="modalClose">×</button></div><p class="modal-copy">We could not complete sign out. Please retry.</p><button class="primary wide" id="retrySignOut">Try again</button>`);document.getElementById('retrySignOut')?.addEventListener('click',()=>void openSignin());}return;}try{const result=await auth.signIn({scope:'openid email profile offline_access'});document.getElementById('modalRoot')?.remove();await syncAuthButton();if(result?.user?.name){const button=document.getElementById('signin');if(button)button.textContent=`Account · ${result.user.name}`;}}catch(err){const code=typeof err==='object'&&err&&'code' in err?String((err as {code?:unknown}).code):'auth_error';const message=code==='popup_blocked'?'Your browser blocked the sign-in window. Allow popups for this site and try again.':code==='popup_closed'?'The sign-in window was closed before completion. Sign-in was cancelled.':'Sign-in could not be completed. Please try again or continue with public market research.';modal(`<div class="modal-head"><div><span class="kicker">ACCOUNT ACCESS</span><h2>Sign in</h2></div><button class="close" id="modalClose">×</button></div><div class="auth-status"><span class="result-icon">◉</span><p>${message}</p></div><button class="primary wide" id="retrySignIn">Try sign in again</button><button class="secondary wide" id="continuePublic">Continue without signing in</button>`);document.getElementById('retrySignIn')?.addEventListener('click',()=>void openSignin());document.getElementById('continuePublic')?.addEventListener('click',()=>document.getElementById('modalRoot')?.remove());}}
function openCheckout():void{modal(`<div class="modal-head"><div><span class="kicker">SECURE CHECKOUT</span><h2>CryptoPilot Premium</h2></div><button class="close" id="modalClose">×</button></div><div class="checkout-summary"><div><span>Plan</span><b>Premium · 30 days</b></div><div><span>Total</span><b>3 USDT</b></div><div><span>Network</span><b>TRON · TRC20</b></div></div><div class="checkout-step"><span class="step-number">1</span><div><b>Confirm payment method</b><p>Send exactly 3 USDT using the TRC20 network. CryptoPilot is non-custodial.</p></div></div><button class="primary wide" id="revealPayment">Continue to payment</button><div id="paymentPanel" class="payment-panel hidden"><div class="checkout-step"><span class="step-number">2</span><div><b>Send payment</b><p>Only now is the receiving wallet shown.</p></div></div><div class="wallet-box"><span>TRC20 receiving wallet</span><code>TLSqNCn8Jdsh6eV4kty3sdeWhcpJFPeVS5</code><button id="copyCheckout">Copy wallet</button></div><a class="scan-link" href="https://tronscan.org/#/address/TLSqNCn8Jdsh6eV4kty3sdeWhcpJFPeVS5" target="_blank" rel="noreferrer">View wallet on TronScan ↗</a><div class="checkout-step"><span class="step-number">3</span><div><b>Verify payment</b><p>Paste your confirmed TRON transaction hash.</p></div></div><input class="form-input" id="txHash" placeholder="TRON transaction hash" /><button class="primary wide" id="verifyPayment">Verify payment on-chain</button><div id="paymentStatus" class="payment-status"></div></div>`);document.getElementById('revealPayment')?.addEventListener('click',()=>{document.getElementById('paymentPanel')?.classList.remove('hidden');document.getElementById('revealPayment')?.remove();});document.getElementById('copyCheckout')?.addEventListener('click',async()=>{await navigator.clipboard.writeText('TLSqNCn8Jdsh6eV4kty3sdeWhcpJFPeVS5');const b=document.getElementById('copyCheckout') as HTMLButtonElement;b.textContent='Copied';});document.getElementById('verifyPayment')?.addEventListener('click',()=>void verifyPayment());}
async function verifyPayment():Promise<void>{const status=document.getElementById('paymentStatus');const hash=(document.getElementById('txHash') as HTMLInputElement)?.value.trim();if(!status)return;if(!/^[a-fA-F0-9]{20,100}$/.test(hash)){status.className='payment-status error';status.textContent='Enter a valid TRON transaction hash (hex) first.';return;}status.className='payment-status';status.textContent='Checking confirmed TRC20 transfer…';try{const {data}=await api.post('/api/payment/verify',{txHash:hash});status.className=data.verified?'payment-status success':'payment-status error';status.textContent=data.verified?`Payment verified: ${data.amount} USDT received.`:String(data.message||'Payment not found or does not match the required transfer.');if(data.verified){localStorage.setItem('cp_premium',JSON.stringify({verifiedAt:new Date().toISOString(),amount:data.amount,transaction:data.transaction}));const panel=document.getElementById('paymentPanel');if(panel)panel.insertAdjacentHTML('beforeend','<div class="premium-verified">✓ Premium payment verified for this browser.</div>');}}catch{status.className='payment-status error';status.textContent='Verification service is temporarily unavailable. Please retry.';}}
async function runAgent():Promise<void>{const button=document.getElementById('agentRun') as HTMLButtonElement|null;const input=document.getElementById('agentPrompt') as HTMLTextAreaElement|null;const output=document.getElementById('agentResult');if(!button||!input||!output)return;button.disabled=true;button.textContent='Agent working…';output.innerHTML='<span class="result-icon spin">✦</span><p>Fetching fresh context and reasoning through the market…</p>';document.getElementById('agentTimeline')?.classList.add('running');try{const {data}=await api.post('/api/ai/agent',{prompt:input.value,assets});output.innerHTML=`<span class="result-icon">✦</span><p>${esc(data?.text||'Agent completed without a readable brief.').replace(/\n/g,'<br>')}</p>`;}catch{output.innerHTML='<span class="result-icon">!</span><p>Agent is temporarily unavailable. The market workspace is still live. Retry the agent in a moment.</p>';}button.disabled=false;button.textContent='Run AI Agent';}
async function prepareChartFile():Promise<void>{const input=document.getElementById('chartFile') as HTMLInputElement|null;const file=input?.files?.[0];const preview=document.getElementById('chartPreview');if(!file||!preview)return;if(file.size>6*1024*1024){preview.innerHTML='<span class="error-text">Image is larger than 6 MB.</span>';preview.classList.remove('hidden');return;}const prepared=await image.resizeIfNeeded(file,{maxDimension:1600,maxPixels:2000000,quality:.82,mimeType:'image/jpeg'});preview.innerHTML=`<img src="data:${prepared.mimeType};base64,${prepared.data}" alt="Trading screenshot preview" /><span>Screenshot ready for AI analysis · ${Math.round(prepared.bytes/1024)} KB</span>`;preview.classList.remove('hidden');}
async function analyzeScreenshot():Promise<void>{const input=document.getElementById('chartFile') as HTMLInputElement|null;const file=input?.files?.[0];const result=document.getElementById('chartResult');const button=document.getElementById('analyzeScreenshot') as HTMLButtonElement|null;if(!file||!result||!button){if(result)result.innerHTML='<span class="result-icon">!</span><p>Choose a trading screenshot first.</p>';return;}if(!isPremiumUnlocked()&&screenshotFreeUses()>=3){modal(`<div class="modal-head"><div><span class="kicker">FREE LIMIT REACHED</span><h2>Unlock more Screenshot AI</h2></div><button class="close" id="modalClose">×</button></div><p class="modal-copy">You have used all 3 free online screenshot analyses. Premium removes this limit and unlocks AI chart analysis, AI Agent, Trade Vision and advanced research tools.</p><a class="primary wide-link" href="#/premium">Get Premium · 3 USDT / 30 days →</a>`);return;}button.disabled=true;button.textContent='AI analyzing…';result.innerHTML='<span class="result-icon spin">✦</span><p>Reading visible chart structure, trend and risk…</p>';try{const prepared=await image.resizeIfNeeded(file,{maxDimension:1600,maxPixels:2000000,quality:.82,mimeType:'image/jpeg'});const {data}=await api.post('/api/ai/chart-analysis',{image:{data:prepared.data,mimeType:prepared.mimeType}});if(!data?.ok)throw new Error('Analysis unavailable');if(!isPremiumUnlocked()){const next=Math.min(3,screenshotFreeUses()+1);localStorage.setItem('cp_screenshot_free_uses',String(next));}const remaining=Math.max(0,3-screenshotFreeUses());result.innerHTML=`<span class="result-icon">✦</span><p>${esc(data.text||'No readable analysis returned.').replace(/\n/g,'<br>')}<br><br><span class="muted">${isPremiumUnlocked()?'Premium active · unlimited Screenshot AI':remaining>0?`${remaining} free analysis${remaining===1?'':'es'} remaining.`:'3 free analyses used. Premium unlocks continued analysis.'}</span></p>`;}catch{result.innerHTML='<span class="result-icon">!</span><p>Chart analysis is temporarily unavailable. Check the image and retry.</p>';}button.disabled=false;button.textContent=isPremiumUnlocked()?'Analyze screenshot with AI':screenshotFreeUses()>=3?'Unlock more AI analyses':'Analyze screenshot with AI';}
async function refreshMarketStatus():Promise<void>{try{const {data}=await api.get('/api/market-status');const el=document.getElementById('liveLabel');if(el)el.textContent=data.online?`LIVE · ${String(data.providers?.[0]||'MARKET').toUpperCase()}`:'MARKET DATA DEGRADED';}catch{const el=document.getElementById('liveLabel');if(el)el.textContent='MARKET DATA DEGRADED';}}
async function loadPulse():Promise<void>{try{const {data}=await api.get('/api/market-pulse');pulse={gainers:data.gainers||[],losers:data.losers||[]};}catch{pulse={gainers:[],losers:[]};}}
async function fetchClientMarket():Promise<Asset[]>{const hosts=['api.binance.com','api1.binance.com','api2.binance.com','api3.binance.com'];for(const host of hosts){try{const r=await fetch(`https://${host}/api/v3/ticker/24hr`,{cache:'no-store'});if(!r.ok)continue;const rows=await r.json() as Array<{symbol:string;lastPrice:string;priceChangePercent:string;quoteVolume:string}>;const assets=rows.filter(r=>r.symbol.endsWith('USDT')&&Number(r.lastPrice)>0&&!/(UP|DOWN|BULL|BEAR)$/.test(r.symbol.replace('USDT',''))).map(r=>({symbol:r.symbol.slice(0,-4),name:r.symbol.slice(0,-4),price:Number(r.lastPrice),change:Number(r.priceChangePercent),volume:Number(r.quoteVolume),source:'Binance'})).sort((a,b)=>b.volume-a.volume);if(assets.length>=100)return assets;}catch{continue;}}return [];}
async function loadMarket(forceRender=false):Promise<void>{if(marketRefreshInFlight)return;marketRefreshInFlight=true;try{const {data}=await api.get('/api/market') as {data:MarketResponse & {count?:number}};let nextAssets=Array.isArray(data.assets)?data.assets:[];if(nextAssets.length<100){const clientAssets=await fetchClientMarket();if(clientAssets.length>nextAssets.length)nextAssets=clientAssets;}if(nextAssets.length)assets=nextAssets;discovery.totalMarkets=data.count||assets.length;const el=document.getElementById('liveLabel');if(el)el.textContent=assets.length>=100?'LIVE · MARKET UNIVERSE':'MARKET DATA DEGRADED';await loadPulse();try{const found=await api.get('/api/discovery');if(found.data?.ok)discovery={totalMarkets:found.data.totalMarkets||discovery.totalMarkets,newlyListed:found.data.newlyListed||[],trending:found.data.trending||[],pumpers:found.data.pumpers||[]};}catch{}if(forceRender||!marketInitialized){marketInitialized=true;render();}else{const cards=document.querySelector('.market-grid');if(cards&&route==='home')cards.innerHTML=assets.slice(0,12).map(assetCard).join('');const risk=document.querySelector('.risk-widget');if(risk&&route==='home')risk.outerHTML=riskWidget();if(route==='markets'){const results=document.getElementById('marketResults');if(results){const q=(document.getElementById('marketSearch') as HTMLInputElement|null)?.value.toUpperCase()||'';const rows=assets.filter(a=>!q||a.symbol.includes(q)||String(a.name||'').toUpperCase().includes(q)).slice(0,500);results.innerHTML=rows.length?`<div class="market-table-head"><span>#</span><span>Coin</span><span>Price</span><span>24h Movement</span><span>24h Volume</span><span>Market Cap</span></div>${marketTableRows(rows)}`:'<div class="panel empty-state"><div class="feature-icon">⌕</div><h2>No matching markets</h2><p>Try a symbol such as BTC, ETH or SOL.</p></div>';bindInteractions();}}bindInteractions();}}catch{const clientAssets=await fetchClientMarket();if(clientAssets.length>=100){assets=clientAssets;discovery.totalMarkets=clientAssets.length;const el=document.getElementById('liveLabel');if(el)el.textContent='LIVE · BINANCE CLIENT FALLBACK';if(forceRender||!marketInitialized){marketInitialized=true;render();}return;}const el=document.getElementById('liveLabel');if(el)el.textContent='MARKET DATA OFFLINE · RETRYING';if(forceRender&&!marketInitialized){marketInitialized=true;render();}}finally{marketRefreshInFlight=false;}}
function bindMarketTools():void{const search=document.getElementById('marketSearch') as HTMLInputElement|null;const sort=document.getElementById('marketSort') as HTMLSelectElement|null;const results=document.getElementById('marketResults');let filter='all';const draw=()=>{if(!results)return;const q=(search?.value||'').trim().toUpperCase();const mode=sort?.value||'marketCap';let rows=assets.filter(a=>!q||a.symbol.includes(q)||String(a.name||'').toUpperCase().includes(q));if(filter==='gainers')rows=rows.filter(a=>a.change>0);if(filter==='losers')rows=rows.filter(a=>a.change<0);if(filter==='volume')rows=rows.sort((a,b)=>b.volume-a.volume);rows=rows.sort((a,b)=>mode==='change'?b.change-a.change:mode==='volume'?b.volume-a.volume:mode==='price'?b.price-a.price:mode==='name'?String(a.name||a.symbol).localeCompare(String(b.name||b.symbol)):(b.marketCap||0)-(a.marketCap||0));const totalPages=Math.max(1,Math.ceil(rows.length/500));if(marketPage>totalPages)marketPage=totalPages;const start=(marketPage-1)*500;const pageRows=rows.slice(start,start+500);const pagination=`<div class="market-pagination"><button class="secondary" data-market-page="prev" ${marketPage<=1?'disabled':''}>← Previous</button><span>Page <b>${marketPage}</b> of <b>${totalPages}</b> · Showing ${rows.length?start+1:0}-${Math.min(start+500,rows.length)} of ${rows.length}</span><button class="secondary" data-market-page="next" ${marketPage>=totalPages?'disabled':''}>Next →</button></div>`;results.innerHTML=pageRows.length?`<div class="market-table-head"><span>#</span><span>Coin</span><span>Price</span><span>24h Movement</span><span>24h Volume</span><span>Market Cap</span></div>${marketTableRows(pageRows,start)}${pagination}`:'<div class="panel empty-state"><div class="feature-icon">⌕</div><h2>No matching markets</h2><p>Try a symbol such as BTC, ETH or SOL.</p></div>';document.querySelectorAll<HTMLElement>('#marketResults [data-asset]').forEach(el=>el.addEventListener('click',()=>openAsset(el.dataset.asset||'BTC')));document.querySelector('[data-market-page="prev"]')?.addEventListener('click',()=>{if(marketPage>1){marketPage--;draw();}});document.querySelector('[data-market-page="next"]')?.addEventListener('click',()=>{if(marketPage<totalPages){marketPage++;draw();document.getElementById('marketResults')?.scrollIntoView({behavior:'smooth'});}});};search?.addEventListener('input',()=>{marketPage=1;draw();});sort?.addEventListener('change',()=>{marketPage=1;draw();});document.querySelectorAll<HTMLButtonElement>('[data-market-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.marketFilter||'all';document.querySelectorAll<HTMLButtonElement>('[data-market-filter]').forEach(x=>x.classList.toggle('active',x===button));marketPage=1;draw();}));draw();}
function bindPortfolio():void{const watchKey='cp_watchlist';const holdingKey='cp_holdings';const render=()=>{const items=JSON.parse(localStorage.getItem(watchKey)||'[]') as string[];const holdings=JSON.parse(localStorage.getItem(holdingKey)||'[]') as Array<{asset:string;qty:number;cost:number}>;const watch=document.getElementById('watchlist');if(watch)watch.innerHTML=items.length?items.map(s=>`<button class="list-row" data-asset="${esc(s)}"><b>${esc(s)}</b><span>Saved locally</span><span>Open →</span></button>`).join(''):'No assets saved yet.';document.querySelectorAll<HTMLElement>('#watchlist [data-asset]').forEach(e=>e.addEventListener('click',()=>openAsset(e.dataset.asset||'BTC')));let total=0;const rows=holdings.map(h=>{const a=assets.find(x=>x.symbol===h.asset);const price=a?.price||0;const value=price*h.qty;const pnl=(price-h.cost)*h.qty;total+=value;return `<div class="list-row"><b>${esc(h.asset)}</b><span>${h.qty.toLocaleString()} · ${money(value)}</span><strong class="${pnl>=0?'green':'red'}">${pnl>=0?'+':''}${money(pnl)}</strong></div>`;}).join('');const totalEl=document.getElementById('portfolioTotal');if(totalEl)totalEl.textContent=money(total);const rowsEl=document.getElementById('portfolioRows');if(rowsEl)rowsEl.innerHTML=rows||'No holdings yet.';};document.getElementById('saveHolding')?.addEventListener('click',()=>{const asset=(document.getElementById('holdingAsset') as HTMLSelectElement).value;const qty=Number((document.getElementById('holdingQty') as HTMLInputElement).value);const cost=Number((document.getElementById('holdingCost') as HTMLInputElement).value);const msg=document.getElementById('holdingMsg');if(!qty||qty<=0||!cost||cost<=0){if(msg)msg.textContent='Enter a positive quantity and average cost.';return;}const holdings=JSON.parse(localStorage.getItem(holdingKey)||'[]') as Array<{asset:string;qty:number;cost:number}>;const existing=holdings.find(h=>h.asset===asset);if(existing){existing.qty=qty;existing.cost=cost;}else holdings.push({asset,qty,cost});localStorage.setItem(holdingKey,JSON.stringify(holdings));if(msg)msg.textContent=`${asset} position saved locally.`;render();});document.getElementById('addWatch')?.addEventListener('click',()=>{const items=JSON.parse(localStorage.getItem(watchKey)||'[]') as string[];if(!items.includes('BTC'))items.push('BTC');localStorage.setItem(watchKey,JSON.stringify(items));render();});render();}
function bindAlerts():void{const key='cp_alerts';const render=()=>{const items=JSON.parse(localStorage.getItem(key)||'[]') as Array<{asset:string;pct:number;base:number;triggered?:boolean}>;const el=document.getElementById('alertsList');if(el)el.innerHTML=items.length?items.map((a,i)=>`<div class="list-row"><b>${esc(a.asset)}</b><span>${a.pct}% from ${money(a.base)}</span><span>${a.triggered?'Triggered':'Monitoring'}</span><button class="chip" data-remove-alert="${i}">Remove</button></div>`).join(''):'No alerts created yet.';document.querySelectorAll<HTMLElement>('[data-remove-alert]').forEach(e=>e.addEventListener('click',()=>{const current=JSON.parse(localStorage.getItem(key)||'[]') as Array<{asset:string;pct:number;base:number;triggered?:boolean}>;current.splice(Number(e.dataset.removeAlert),1);localStorage.setItem(key,JSON.stringify(current));render();}));};document.getElementById('saveAlert')?.addEventListener('click',async()=>{const asset=(document.getElementById('alertAsset') as HTMLSelectElement).value;const pct=Number((document.getElementById('alertPct') as HTMLInputElement).value);const live=assets.find(a=>a.symbol===asset);const m=document.getElementById('alertMsg');if(!pct||pct<=0||!live){if(m)m.textContent='Choose an asset and enter a positive percentage.';return;}if('Notification' in window&&Notification.permission==='default')await Notification.requestPermission();const items=JSON.parse(localStorage.getItem(key)||'[]') as Array<{asset:string;pct:number;base:number;triggered?:boolean}>;items.push({asset,pct,base:live.price});localStorage.setItem(key,JSON.stringify(items));if(m)m.textContent=`Monitoring ${asset} from ${money(live.price)}. Keep this tab open for browser checks.`;render();});render();}
window.addEventListener('hashchange',()=>{route=getRoute();render();});
render();
void loadMarket();
window.setInterval(()=>{if(document.visibilityState==='visible'||route==='home'||route==='markets')void loadMarket(false);void checkBrowserAlerts();},10000);
async function checkBrowserAlerts():Promise<void>{const key='cp_alerts';const items=JSON.parse(localStorage.getItem(key)||'[]') as Array<{asset:string;pct:number;base:number;triggered?:boolean}>;if(!items.length)return;const changed=items.map(item=>{const live=assets.find(a=>a.symbol===item.asset);if(!live||item.triggered)return item;const move=Math.abs((live.price-item.base)/item.base*100);if(move>=item.pct){item.triggered=true;if('Notification' in window&&Notification.permission==='granted')new Notification(`CryptoPilot alert · ${item.asset}`,{body:`${item.asset} moved ${move.toFixed(2)}% from your ${money(item.base)} baseline.`});}return item;});localStorage.setItem(key,JSON.stringify(changed));if(route==='alerts')bindAlerts();}
